  Lemma pv_jt_read : ltac2:(zQ "h30!n2!p5!pa!u5!hj2!hn5!hne!ho3!ho9!hp3!hpa!r5!h9!ht7!hu8!iie!ij5!ik0!ik6>1m>0@1$1@1$0#k0@1$3@1$1@1$0#8>1c$c>0@2$h0$5^2>0@2$a@2$6+9^2@2$6^2+nb@3$b@1$3@1$2@1$1@1$0#8@4$d$5^4@2$8@1$0#k0@2$h1$4@2$h2+4@2$7^3+9N4@2$9@1$2@1$1@1$0#8@1$f@2$8@1$0#k0@2$7@1$e^3$4").
Proof.
  intros m c MI HC.
  assert (K : exists k : nat, (k < 115)%nat /\ c = 9 + Z.of_nat k) by (exists (Z.to_nat (c - 9)); lia).
  destruct K as [k [Hk ->]].
  do 115 (destruct k as [|k]; [pv_jt_case MI|]); lia.
Qed.

